code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    best = None
    best_size = -1
    for r0 in range(h - 2):
        for r1 in range(r0 + 2, h):
            for c0 in range(w - 2):
                for c1 in range(c0 + 2, w):
                    inside = [grid[r][c] for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
                    if not inside or len(set(inside)) != 1:
                        continue
                    fill_color = inside[0]
                    border = [(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                              if r in (r0, r1) or c in (c0, c1)]
                    counts = {}
                    for r, c in border:
                        counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
                    for wall_color, count in counts.items():
                        if wall_color == fill_color:
                            continue
                        gaps = [(r, c) for r, c in border if grid[r][c] == fill_color]
                        if len(gaps) <= 1 and count == len(border) - len(gaps):
                            size = len(inside) + len(gaps)
                            if size > best_size:
                                best_size = size
                                best = (r0, r1, c0, c1, gaps)
    out = [row[:] for row in grid]
    if best is not None:
        r0, r1, c0, c1, gaps = best
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                out[r][c] = 4
        for r, c in gaps:
            out[r][c] = 4
    return out
